const recalculatePickupRunCounters = `-- name: RecalculatePickupRunCounters :exec
UPDATE pickup_runs r
SET planned_stops = c.total, completed_stops = c.completed
FROM (
    SELECT count(*) FILTER (WHERE status NOT IN ('CANCELLED','REASSIGNED','REJECTED')) AS total,
           count(*) FILTER (WHERE status = 'COMPLETED') AS completed
    FROM pickup_assignments WHERE pickup_run_id = $1
) c
WHERE r.id = $1
`

func (q *Queries) RecalculatePickupRunCounters(ctx context.Context, runID int64) error {
	_, err := q.db.Exec(ctx, recalculatePickupRunCounters, runID)
	return err
}

